package operate_log

import (
	"encoding/json"
	"net/url"
	"strings"
)

func setQueryIfNotEmpty(query url.Values, key, value string) {
	value = strings.TrimSpace(value)
	if value != "" {
		query.Set(key, value)
	}
}

func normalizePositive(value, fallback int) int {
	if value <= 0 {
		return fallback
	}
	return value
}

func normalizeRange(value, fallback, min, max int) int {
	if value <= 0 {
		value = fallback
	}
	if value < min {
		return min
	}
	if value > max {
		return max
	}
	return value
}

func marshalPretty(v interface{}) (string, error) {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

package operate_log

import (
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"

	"github.com/ai-agent-os/ai-agent-os/dto"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/app"
	"github.com/ai-agent-os/ai-agent-os/sdk/agent-app/response"
)

type GeneralReq struct {
	TenantUser         string `json:"tenant_user" widget:"name:租户用户;type:input"`
	ActorUser          string `json:"actor_user" widget:"name:操作用户;type:input"`
	TargetUser         string `json:"target_user" widget:"name:目标用户;type:input"`
	App                string `json:"app" widget:"name:应用;type:input"`
	ResourceType       string `json:"resource_type" widget:"name:资源类型;type:select;options:,table,form,team_access,directory,function"`
	ResourcePath       string `json:"resource_path" widget:"name:资源路径;type:input"`
	ResourcePathPrefix string `json:"resource_path_prefix" widget:"name:资源路径前缀;type:input"`
	RowID              int64  `json:"row_id" widget:"name:记录 ID;type:number;min:0"`
	Action             string `json:"action" widget:"name:操作类型;type:input"`
	Status             string `json:"status" widget:"name:状态;type:select;options:,success,failed"`
	Keyword            string `json:"keyword" widget:"name:关键词;type:input"`
	Page               int    `json:"page" widget:"name:页码;type:number;min:1;render_default:1"`
	PageSize           int    `json:"page_size" widget:"name:每页数量;type:number;min:1;max:100;render_default:20"`
	OrderBy            string `json:"order_by" widget:"name:排序;type:input;placeholder:默认 created_at DESC"`
}

type GeneralResp struct {
	Total    int64  `json:"total" widget:"name:总数;type:number"`
	Page     int    `json:"page" widget:"name:页码;type:number"`
	PageSize int    `json:"page_size" widget:"name:每页数量;type:number"`
	LogsJSON string `json:"logs_json" widget:"name:日志 JSON;type:text_area"`
}

func General(ctx *app.Context, resp response.Response) error {
	var req GeneralReq
	if err := ctx.ShouldBindValidate(&req); err != nil {
		return err
	}
	query := url.Values{}
	setQueryIfNotEmpty(query, "tenant_user", req.TenantUser)
	setQueryIfNotEmpty(query, "actor_user", req.ActorUser)
	setQueryIfNotEmpty(query, "target_user", req.TargetUser)
	setQueryIfNotEmpty(query, "app", req.App)
	setQueryIfNotEmpty(query, "resource_type", req.ResourceType)
	setQueryIfNotEmpty(query, "resource_path", req.ResourcePath)
	setQueryIfNotEmpty(query, "resource_path_prefix", req.ResourcePathPrefix)
	setQueryIfNotEmpty(query, "action", req.Action)
	setQueryIfNotEmpty(query, "status", req.Status)
	setQueryIfNotEmpty(query, "keyword", req.Keyword)
	setQueryIfNotEmpty(query, "order_by", req.OrderBy)
	if req.RowID > 0 {
		query.Set("row_id", strconv.FormatInt(req.RowID, 10))
	}
	query.Set("page", strconv.Itoa(normalizePositive(req.Page, 1)))
	query.Set("page_size", strconv.Itoa(normalizeRange(req.PageSize, 20, 1, 100)))

	var result dto.GetOperateLogsResp
	if err := ctx.APICall(http.MethodGet, "/workspace/api/v1/operate_log/general?"+query.Encode(), nil, &result); err != nil {
		return fmt.Errorf("[系统错误]-[OperateLogGeneral] 查询操作日志失败, req: %+v, err: %w", req, err)
	}
	logsJSON, err := marshalPretty(result.Logs)
	if err != nil {
		return err
	}
	return resp.Form(&GeneralResp{
		Total:    result.Total,
		Page:     result.Page,
		PageSize: result.PageSize,
		LogsJSON: strings.TrimSpace(logsJSON),
	}).Build()
}

var GeneralTemplate = &app.FormTemplate{
	BaseConfig: app.BaseConfig{
		Name:     "查询操作日志",
		Desc:     "查询统一操作日志。支持 Table、Form、权限等资源类型，数据来自 operate_logs。",
		Tags:     []string{"操作日志", "平台接口", "只读"},
		Request:  &GeneralReq{},
		Response: &GeneralResp{},
	},
}

func init() {
	packageContext.POST("general.form", General, GeneralTemplate)
}

